def _assert_split_is_lossless(bind) -> None:
    failures = []
    for label, sql in _PREFLIGHT_ASSERTIONS:
        violations = bind.execute(sa.text(sql)).scalar_one()
        if violations:
            failures.append(f"  - {label}: {violations} violation(s)")
    if failures:
        raise RuntimeError(
            "Refusing to split `competition`: the data no longer supports a "
            "lossless decomposition.\n"
            + "\n".join(failures)
            + "\nSplitting anyway would force an arbitrary choice about which "
            "value survives. Reconcile the conflicting rows first."
        )


